def ic(n):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[n]+'</svg>'
def art(n=0,large=False):return f'<div class="art a{n%5} {"large" if large else ""}"><span>SONIC<br>LANDSCAPES</span><i>{["01","02","03","04","05"][n%5]}</i></div>'
def btn(text,icon=None,primary=False):return f'<button class="{"primary" if primary else "secondary"}">{ic(icon) if icon else ""}{text}</button>'
def chips(labels,sel=0):return '<div class="chips">'+''.join(f'<button class="chip {"selected" if i==sel else ""}">{v}</button>' for i,v in enumerate(labels))+'</div>'
def row(title,sub,n=0,tail='more'):return f'<div class="row">{art(n)}<div class="grow"><strong>{title}</strong><small>{sub}</small></div><button class="icon" aria-label="Mais opções">{ic('forward' if tail=='back' else tail)}</button></div>'
def search(text):return f'<div class="search">{ic("search")}<span>{text}</span></div>'
def nav(active=0):return '<nav>'+''.join(f'<button class="{"active" if i==active else ""}">{ic(k)}<span>{v}</span></button>' for i,(k,v) in enumerate([('home','Início'),('search','Busca'),('library','Biblioteca'),('settings','Ajustes')]))+'</nav>'
def mini():return f'<div class="mini">{art(0)}<div class="grow"><strong>Pilot the Dune</strong><small>Slo Burn</small></div><button class="icon">{ic("pause")}</button><button class="icon">{ic("queue")}</button><div class="progress"></div></div>'
def section(t,more=''):return f'<div class="section"><h3>{t}</h3><span>{more}</span></div>'
def top(title,sub='',back=False):return f'<header>{ic("back") if back else ""}<div class="grow"><h2>{title}</h2>{"<small>"+sub+"</small>" if sub else ""}</div><button class="icon">{ic("more")}</button></header>'
def phone(title,body,active=0,player=False):return f'<article class="sample"><div class="label">{title}</div><div class="phone"><div class="status"><b>9:41</b><span>▂ ▄ ▆ &nbsp; ▰</span></div>{body if player else "<div class=content>"+body+"</div><div class=dock>"+mini()+nav(active)+"</div>"}<div class="gesture"></div></div></article>'
