html='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BZtune Android — proposta visual</title><style>'+css+'</style><div class="document-head"><h1>BZtune<span style="color:#ffbd69">.</span> Android — direção visual</h1><p><b>PROPOSTA · NÃO IMPLEMENTADA</b> — 12 telas de revisão. Conteúdo e números ilustrativos; capas geométricas fictícias. Controles demonstram a organização visual, sem conexão com o aplicativo.</p></div>'
for i in range(3):html+='<section class="board" id="board'+str(i+1)+'"><div class="board-title">'+['01 — DESCOBRIR E NAVEGAR','02 — ORGANIZAR E OUVIR','03 — GERENCIAR E RECUPERAR'][i]+'</div>'+''.join(screens[i*4:i*4+4])+'</section>'
html+='<p class="footer-note">Preservar: arquivos locais, favoritas, coleção, playlists, fila, shuffle, repetição, seek ±10s, backup e consulta MusicBrainz. Letras, equalizador, crossfade e streaming não estão implementados no Android. Este estudo não oferece esses controles.</p></html>'
(out/'proposta-visual.html').write_text(html)
